lse}>搜索</a><a href="/resources" class:active={isActive('/resources')} onclick={()=>menuOpen=false}>资源</a><a href="/tags" class:active={isActive('/tags')} onclick={()=>menuOpen=false}>标签</a><a href="/series" class:active={isActive('/series')} onclick={()=>menuOpen=false}>系列</a><a href="/about" class:active={isActive('/about')} onclick={()=>menuOpen=false}>关于</a></nav>{/if}</header>
